CREATE TABLE roles (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE);
INSERT INTO roles(name) VALUES ('USER'),('ADMIN');
CREATE TABLE users (id UUID PRIMARY KEY, name VARCHAR(255), last_name VARCHAR(255), email VARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255), is_active BOOLEAN NOT NULL DEFAULT FALSE, is_verified BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP, updated_at TIMESTAMP, session_version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE user_roles (user_id UUID NOT NULL REFERENCES users, role_id BIGINT NOT NULL REFERENCES roles, PRIMARY KEY(user_id,role_id));
CREATE TABLE formats (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(255) NOT NULL UNIQUE, price NUMERIC(10,2) NOT NULL CHECK(price > 0));
CREATE TABLE cinemas (id UUID PRIMARY KEY, name VARCHAR(255) NOT NULL, img VARCHAR(255), address VARCHAR(255) NOT NULL, second_address VARCHAR(255), city VARCHAR(255) NOT NULL, latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, room_quantity INTEGER, description VARCHAR(1000));
CREATE UNIQUE INDEX cinema_name_unique ON cinemas(LOWER(name));
CREATE TABLE cinema_formats (cinema_id UUID NOT NULL REFERENCES cinemas, format_id BIGINT NOT NULL REFERENCES formats, PRIMARY KEY(cinema_id,format_id));
CREATE TABLE cinema_rooms (id UUID PRIMARY KEY, name VARCHAR(255), capacity INTEGER, seat_per_row INTEGER, cinema_id UUID REFERENCES cinemas, UNIQUE(cinema_id,name));
CREATE TABLE seats (id UUID PRIMARY KEY, "row" VARCHAR(255) NOT NULL, number INTEGER NOT NULL CHECK(number > 0), pos_x INTEGER NOT NULL CHECK(pos_x >= 0), pos_y INTEGER NOT NULL CHECK(pos_y >= 0), room_id UUID NOT NULL REFERENCES cinema_rooms, UNIQUE(room_id,"row",number), UNIQUE(room_id,pos_x,pos_y));
CREATE TABLE movies (id UUID PRIMARY KEY, title VARCHAR(255), description VARCHAR(255), poster_url VARCHAR(255), classification VARCHAR(255), duration INTEGER NOT NULL CHECK(duration > 0), genre VARCHAR(255), is_new_release BOOLEAN, is_pre_sale BOOLEAN, opening_date TIMESTAMP);
CREATE UNIQUE INDEX movie_title_unique ON movies(LOWER(title));
CREATE TABLE show_times (id UUID PRIMARY KEY, movie_id UUID REFERENCES movies, cinema_room_id UUID REFERENCES cinema_rooms, format_id BIGINT REFERENCES formats, start_time TIMESTAMP, end_time TIMESTAMP, CHECK(end_time > start_time));
CREATE INDEX showtime_movie_start ON show_times(movie_id,start_time);
CREATE INDEX showtime_room_start ON show_times(cinema_room_id,start_time);
CREATE TABLE bookings (id UUID PRIMARY KEY, code VARCHAR(255) NOT NULL UNIQUE, booking_status VARCHAR(255) NOT NULL, payment_status VARCHAR(255), sub_total NUMERIC(38,2) NOT NULL, tax NUMERIC(38,2) NOT NULL, total NUMERIC(38,2) NOT NULL, creat_at TIMESTAMP NOT NULL, expired_at TIMESTAMP, show_time_entity_id UUID REFERENCES show_times, user_id UUID REFERENCES users);
CREATE INDEX booking_user_created ON bookings(user_id,creat_at);
CREATE TABLE booking_details (id UUID PRIMARY KEY, seat_label VARCHAR(255) NOT NULL, ticket_type VARCHAR(255), price NUMERIC(10,2) NOT NULL, booking_id UUID REFERENCES bookings);
CREATE TABLE seat_occupations (show_time_id UUID NOT NULL REFERENCES show_times, seat_id UUID NOT NULL REFERENCES seats, booking_id UUID NOT NULL REFERENCES bookings, PRIMARY KEY(show_time_id,seat_id));
CREATE INDEX occupation_booking ON seat_occupations(booking_id);
CREATE TABLE refresh_token (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id UUID REFERENCES users, token VARCHAR(255) NOT NULL UNIQUE, expiry_date TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE email_verifications (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id UUID REFERENCES users, code VARCHAR(255), email VARCHAR(255) UNIQUE, expires_at TIMESTAMP, attempts INTEGER NOT NULL DEFAULT 0, sent_at TIMESTAMP);
CREATE TABLE oauth_identities (provider VARCHAR(30) NOT NULL, subject VARCHAR(255) NOT NULL, user_id UUID NOT NULL REFERENCES users, PRIMARY KEY(provider,subject));
CREATE TABLE oauth_codes (code_hash VARCHAR(64) PRIMARY KEY, user_id UUID REFERENCES users, provider VARCHAR(30), subject VARCHAR(255), email VARCHAR(255), expires_at TIMESTAMP NOT NULL);
CREATE TABLE mail_outbox (id UUID PRIMARY KEY, recipient VARCHAR(255) NOT NULL, subject VARCHAR(255) NOT NULL, body TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_attempt TIMESTAMP NOT NULL, sent BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE auth_limits (bucket VARCHAR(255) PRIMARY KEY, attempts INTEGER NOT NULL, expires_at TIMESTAMP NOT NULL);
CREATE TABLE payment_attempts (id UUID PRIMARY KEY, booking_id UUID NOT NULL UNIQUE REFERENCES bookings, session_id VARCHAR(255) UNIQUE, payment_intent_id VARCHAR(255), checkout_url TEXT, state VARCHAR(40) NOT NULL, refund_id VARCHAR(255), refund_generation INTEGER NOT NULL DEFAULT 0, checkout_expires_at TIMESTAMP NOT NULL, last_error VARCHAR(255), updated_at TIMESTAMP NOT NULL);
CREATE TABLE payment_events (event_id VARCHAR(255) PRIMARY KEY, processed_at TIMESTAMP NOT NULL);
